[[ ## document ## ]]
{
  "title": "COGS Bridge Schedule — Q2 to Q3 Dollar Breakdown per Margin Driver",
  "path": "engagements/dana-manufacturing/board-materials/q3-cogs-bridge-schedule.docx",
  "document": {
    "blocks": [
      {
        "kind": "heading",
        "level": 1,
        "text": "COGS Bridge Schedule: Q2 to Q3 Margin Decline"
      },
      {
        "kind": "paragraph",
        "text": "Prepared for Dana's board slide. All figures in USD thousands. Bridge reconciles the change in cost of goods sold from Q2 to Q3, isolating the dollar impact of each margin driver."
      },
      {
        "kind": "heading",
        "level": 2,
        "text": "Summary Bridge"
      },
      {
        "kind": "table",
        "columns": ["Driver", "Q2 to Q3 $ Impact", "Direction", "Notes"],
        "rows": [
          ["COGS — Q2 baseline", "12,400", "—", "Q2 actual COGS"],
          ["Raw material price increase", "+680", "Unfavorable", "Steel +4.2%; resin +3.1%"],
          ["Freight & logistics", "+240", "Unfavorable", "Carrier surcharges; longer lead times"],
          ["Labor rate & overtime", "+310", "Unfavorable", "Overtime premium during line changeover"],
          ["Product mix shift", "-95", "Favorable", "Higher proportion of premium SKUs"],
          ["Scrap & rework", "+185", "Unfavorable", "Changeover-related scrap; 2 rework batches"],
          ["Volume (units)", "-120", "Favorable", "Q3 units down 3.8% vs Q2"],
          ["Other net", "+45", "Unfavorable", "Supplies, utilities, tooling amortization"],
          ["COGS — Q3 actual", "13,645", "—", "Q3 actual COGS; net increase $1,245"],
          ["Net sales decline (COGS impact on margin)", "—", "—", "Net sales down $1,020; margin % declined 2.3 pts"]
        ]
      },
      {
        "kind": "heading",
        "level": 2,
        "text": "Driver Detail"
      },
      {
        "kind": "list",
        "ordered": true,
        "items": [
          "Raw material price increase (+$680): Steel coil purchase price rose from $1,180/ton to $1,230/ton effective July 1; resin index up 3.1% on supplier price letter. Applied to Q3 purchase volume of 11,300 tons and 42,000 lbs resin.",
          "Freight & logistics (+$240): Two new lanes added for expedited delivery after supplier consolidation; average per-shipment cost up $410. Includes $60 of detention charges.",
          "Labor rate & overtime (+$310): Annual merit increase effective July 1 (+2.5% straight time) plus 1,140 hours of overtime at 1.5x during the August line changeover. Overtime premium alone is $175.",
          "Product mix shift (-$95): Favorable mix as premium product line (higher margin, similar COGS per unit) grew from 22% to 26% of units shipped.",
          "Scrap & rework (+$185): Changeover produced 4.1% scrap rate vs 2.6% normal; two customer batches required rework at $62 and $48 per unit labor/material.",
          "Volume (units) (-$120): Units shipped fell from 54,200 to 52,100. Variable COGS per unit was stable at $198; fixed COGS absorbed over fewer units.",
          "Other net (+$45): Utility rate increase ($22), packaging cost increase ($14), and tooling amortization timing ($9)."
        ]
      },
      {
        "kind": "heading",
        "level": 2,
        "text": "Reconciliation Check"
      },
      {
        "kind": "paragraph",
        "text": "Sum of driver impacts: +680 + 240 + 310 - 95 + 185 - 120 + 45 = +1,245. Q3 COGS of $13,645 less Q2 COGS of $12,400 = $1,245. Bridge ties. Supporting detail (purchase price letters, payroll registers, scrap reports) is available in the engagement file."
      }
    ]
  }
}

